SELECT CASE WHEN rating >= 3.7 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, COUNT(*) FILTER (WHERE city = 'Singapore') AS singapore_rows, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, COUNT(*) FILTER (WHERE city = 'Chiang Mai') AS chiang_mai_rows, COUNT(CASE WHEN city = 'Berlin' THEN 1 END) AS berlin_count FROM suppliers GROUP BY CASE WHEN rating >= 3.7 THEN 'LARGE' ELSE 'SMALL' END ORDER BY chiang_mai_rows DESC;
